INSERT INTO public.interpretation_templates VALUES ('8ddf1411-433a-473d-afac-d028ba0d7b77', 'en', 'planet_in_sign', 'Sun', 'Aries', NULL, 'Sun in Aries', 'Your core identity is driven by initiative, courage, and a pioneering spirit. You lead with boldness and thrive when charting new territory.', '{leadership,bold,fire,initiative}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('7247a723-1bc5-4f47-9934-09434519be16', 'en', 'planet_in_sign', 'Sun', 'Taurus', NULL, 'Sun in Taurus', 'Your core identity is anchored in stability, sensory pleasure, and patient determination. You build slowly but create lasting foundations.', '{stability,earth,patience,material}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('e2bc9bb4-0d41-4d71-bc4e-bdd50c3bc173', 'en', 'planet_in_sign', 'Sun', 'Gemini', NULL, 'Sun in Gemini', 'Your identity is shaped by curiosity, versatility, and communication. You thrive on variety and intellectual exchange.', '{communication,air,dual,curious}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('57651c27-bfa8-41ea-818b-1f5f2413bfe7', 'en', 'planet_in_sign', 'Sun', 'Cancer', NULL, 'Sun in Cancer', 'Emotional depth, nurturing instincts, and a strong connection to home and family define your core self.', '{nurture,water,home,emotional}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('c5bee2c7-47db-436e-9782-d834ab824947', 'en', 'planet_in_sign', 'Sun', 'Leo', NULL, 'Sun in Leo', 'Creativity, self-expression, and a warm generous heart form your identity. You shine brightest when given a stage.', '{creative,fire,generous,confidence}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('db4a1b70-2f43-4725-a290-a21c4f35edc1', 'en', 'planet_in_sign', 'Sun', 'Virgo', NULL, 'Sun in Virgo', 'Analytical precision, service orientation, and a sharp eye for detail are the hallmarks of your solar identity.', '{analytical,earth,service,detail}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('bcafed49-a001-4ef6-81b2-d0068cb4f87d', 'en', 'planet_in_sign', 'Sun', 'Libra', NULL, 'Sun in Libra', 'Balance, harmony, and refined aesthetic sensibility define who you are. You are at your best in partnership and diplomacy.', '{balance,air,harmony,diplomat}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('a29e2781-e990-4f2b-9aff-df54f7c48ed5', 'en', 'planet_in_sign', 'Sun', 'Scorpio', NULL, 'Sun in Scorpio', 'Intensity, transformative power, and penetrating insight shape your core identity. You are drawn to depth over surface.', '{intensity,water,transformation,power}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('9b1de8e3-c1f4-4d99-895d-2ce4fb77c8a7', 'en', 'planet_in_sign', 'Sun', 'Sagittarius', NULL, 'Sun in Sagittarius', 'Philosophical vision, love of freedom, and an optimistic quest for truth define your solar nature.', '{freedom,fire,philosophy,optimism}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('a6a1cb43-9932-473d-8202-acd82d2f9588', 'en', 'planet_in_sign', 'Sun', 'Capricorn', NULL, 'Sun in Capricorn', 'Disciplined ambition, structural thinking, and long-term planning are the cornerstones of your identity.', '{ambition,earth,discipline,career}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('33d494d2-9405-4953-90d9-053fb60177b4', 'en', 'planet_in_sign', 'Sun', 'Aquarius', NULL, 'Sun in Aquarius', 'Humanitarian ideals, intellectual independence, and a drive to innovate shape your sense of self.', '{innovation,air,humanitarian,independence}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('fc68e3d3-82f9-447f-abee-6622d4795652', 'en', 'planet_in_sign', 'Sun', 'Pisces', NULL, 'Sun in Pisces', 'Compassion, imagination, and a mystical attunement to the unseen world define your solar identity.', '{compassion,water,mystical,imagination}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('15546291-eeb1-47ea-81d4-4c0400e32643', 'en', 'planet_in_sign', 'Moon', 'Aries', NULL, 'Moon in Aries', 'Your emotional responses are quick, direct, and fiery. You need action to feel emotionally satisfied.', '{impulsive,fire,emotional,reactive}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('6d36d99f-79b8-4f6f-822c-275635877edb', 'en', 'planet_in_sign', 'Moon', 'Taurus', NULL, 'Moon in Taurus', 'Emotional security comes through comfort, routine, and sensory pleasures. You are loyal and deeply steadfast.', '{security,earth,comfort,steadfast}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('1cb3f7bb-38b0-45a0-aef6-22590d351d26', 'en', 'planet_in_sign', 'Moon', 'Gemini', NULL, 'Moon in Gemini', 'Emotional wellbeing depends on mental stimulation and variety. You process feelings through conversation.', '{mental,air,verbal,changeable}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('5e79effc-36d6-4194-b14a-1fd361e354b7', 'en', 'planet_in_sign', 'Moon', 'Cancer', NULL, 'Moon in Cancer', 'You are the Moon''s natural home: deeply intuitive, nurturing, and sensitive to emotional undercurrents.', '{intuitive,water,nurture,home}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('b7278dc8-99ee-4844-bbd5-3b0fd214fd06', 'en', 'planet_in_sign', 'Moon', 'Leo', NULL, 'Moon in Leo', 'You need recognition and warmth to feel emotionally nourished. Drama and creativity fuel your inner world.', '{recognition,fire,drama,warmth}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('a991ef78-9dfc-4a83-8864-c45379f946f5', 'en', 'planet_in_sign', 'Moon', 'Virgo', NULL, 'Moon in Virgo', 'Emotional comfort comes through being useful, organised, and through acts of practical care.', '{practical,earth,service,organised}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('ccbc28b4-bfed-47bd-a2a9-fc9dffdef14a', 'en', 'planet_in_sign', 'Moon', 'Libra', NULL, 'Moon in Libra', 'You find emotional peace in beauty, fairness, and harmonious relationships.', '{harmony,air,beauty,relationships}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('2e6980ad-738c-4152-ba7b-0641d917ff12', 'en', 'planet_in_sign', 'Moon', 'Scorpio', NULL, 'Moon in Scorpio', 'Emotions run deep and intense. You guard vulnerability carefully but feel everything profoundly.', '{intense,water,depth,private}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('ae914076-16dd-42b7-aef0-409df12c32dd', 'en', 'planet_in_sign', 'Moon', 'Sagittarius', NULL, 'Moon in Sagittarius', 'Emotional freedom and the pursuit of meaning bring you inner joy. Confinement is your greatest discomfort.', '{freedom,fire,meaning,adventurous}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('4ef81571-0ddf-4fa5-9646-b337b4a8ed94', 'en', 'planet_in_sign', 'Moon', 'Capricorn', NULL, 'Moon in Capricorn', 'You manage emotions with restraint and find security through achievement and social standing.', '{restraint,earth,achievement,stoic}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('f13a38c3-7c1b-4ccd-afa9-986ee21cd720', 'en', 'planet_in_sign', 'Moon', 'Aquarius', NULL, 'Moon in Aquarius', 'Your emotional needs are met through intellectual community and idealistic causes rather than personal intimacy.', '{community,air,idealistic,detached}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('767cfef3-0d2b-42f5-872e-019d1043eabc', 'en', 'planet_in_sign', 'Moon', 'Pisces', NULL, 'Moon in Pisces', 'You are boundlessly empathetic and spiritually attuned, absorbing the emotional atmosphere around you.', '{empathy,water,spiritual,sensitive}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('736a05e6-88ee-41c8-825a-c389bb98f28e', 'en', 'planet_in_house', 'Sun', '1', NULL, 'Sun in House 1', 'You project a strong, self-assured identity. Life is experienced as a direct expression of personal will.', '{identity,self,projection,vitality}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('f1fc30af-75c6-4169-81c6-0d922eff71a2', 'en', 'planet_in_house', 'Sun', '2', NULL, 'Sun in House 2', 'Your sense of self is closely tied to material security, personal values, and financial independence.', '{money,values,material,security}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('1de320e4-3ee3-4844-b04f-905a4704b420', 'en', 'planet_in_house', 'Sun', '3', NULL, 'Sun in House 3', 'Self-expression through communication, writing, and local connection gives your life purpose.', '{communication,siblings,local,writing}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('39c23eda-1d6d-4621-8646-ba6ee475befa', 'en', 'planet_in_house', 'Sun', '4', NULL, 'Sun in House 4', 'Home, ancestry, and family roots are the foundation of your identity and life purpose.', '{home,family,roots,private}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('6be8d28e-3728-46e1-9fae-248c644a0b1e', 'en', 'planet_in_house', 'Sun', '5', NULL, 'Sun in House 5', 'Creativity, romance, and self-expression are central to your solar purpose. You are at your most vital when playing.', '{creativity,romance,play,children}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('e34cba4f-1206-4917-ba0f-5e75be0955b4', 'en', 'planet_in_house', 'Sun', '6', NULL, 'Sun in House 6', 'Your identity is bound up in work, craft, and health routines. Service and precision give you purpose.', '{work,health,service,routine}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('03d6eeb7-8aed-4077-ad2f-dee79a29c2fb', 'en', 'planet_in_house', 'Sun', '7', NULL, 'Sun in House 7', 'Partnership is a mirror for your deepest self. You discover who you are through significant one-on-one relationships.', '{partnership,marriage,mirror,other}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('4877eb67-c0c7-4a80-a93d-0b22d8acb894', 'en', 'planet_in_house', 'Sun', '8', NULL, 'Sun in House 8', 'Transformation, shared resources, and the mysteries of life and death are your solar domain.', '{transformation,shared,depth,occult}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('e32fb17f-e67f-4fda-a05a-b85fe41b934f', 'en', 'planet_in_house', 'Sun', '9', NULL, 'Sun in House 9', 'Philosophy, long-distance travel, and the pursuit of higher knowledge define your solar path.', '{philosophy,travel,education,belief}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('f696470a-b089-4cad-a758-c433b835240a', 'en', 'planet_in_house', 'Sun', '10', NULL, 'Sun in House 10', 'Career, public reputation, and achievement are the arena in which your solar identity shines brightest.', '{career,status,public,ambition}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('1796724f-8bfb-4f29-b736-8774e0d26b57', 'en', 'planet_in_house', 'Sun', '11', NULL, 'Sun in House 11', 'Your purpose is found in community, friendship, and visionary social causes.', '{community,friends,vision,social}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('571ff322-55da-4e1d-815e-95d342a2ae76', 'en', 'planet_in_house', 'Sun', '12', NULL, 'Sun in House 12', 'Solitude, spiritual practice, and hidden depths nourish your solar identity in ways invisible to others.', '{solitude,spiritual,hidden,retreat}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('09fca4fb-d336-4b86-91ef-7e1e73a95925', 'en', 'planet_in_house', 'Moon', '1', NULL, 'Moon in House 1', 'Your emotional world is immediately visible to others. Moods shift readily and you are highly sensitive to your environment.', '{visible,sensitive,fluctuating,instinctive}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('11395f4f-ddcd-4fde-8034-d8d2fe09e9b7', 'en', 'planet_in_house', 'Moon', '4', NULL, 'Moon in House 4', 'The Moon is powerful in its natural house. Home and family are your emotional bedrock.', '{home,family,roots,stronghold}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('248788fb-e149-4d22-bdf5-302b0af70234', 'en', 'planet_in_house', 'Moon', '7', NULL, 'Moon in House 7', 'Emotional fulfilment is found through close partnership. You seek a nurturing, emotionally safe relationship.', '{partnership,nurture,relationship,safety}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('825e41c0-c5c6-402b-b544-72aed9ec2e12', 'en', 'planet_in_house', 'Moon', '10', NULL, 'Moon in House 10', 'Your emotional needs and professional ambitions are intertwined. Public life has a strongly emotional flavour.', '{career,public,emotional,ambition}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('a82802bf-297b-4776-8643-2616f50b025f', 'en', 'aspect', 'Moon', 'Sun', 'conjunction', 'Sun–Moon Conjunction', 'Your conscious will and emotional instincts are fused into a unified drive. What you want and what you feel are rarely in conflict.', '{unity,identity,instinct,integration}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('c3b4706a-31ee-4161-81a8-ce0dde88c30d', 'en', 'aspect', 'Moon', 'Sun', 'trine', 'Sun–Moon Trine', 'A natural harmony between your ego and emotional nature creates a well-integrated, confident character.', '{harmony,ease,integration,confidence}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('593fb623-3d3f-4191-b09b-b19edea519e1', 'en', 'aspect', 'Moon', 'Sun', 'square', 'Sun–Moon Square', 'Inner tension between your desires and emotional needs propels growth through recurring challenges.', '{tension,growth,challenge,conflict}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('cabed481-7011-4733-9efc-e46e0a7c8d7d', 'en', 'aspect', 'Moon', 'Sun', 'opposition', 'Sun–Moon Opposition', 'A polarity between self-assertion and emotional receptivity plays out through projection onto others.', '{polarity,projection,balance,awareness}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('182e0ba9-07e8-4ba6-b3e7-e5fa3d15e14b', 'en', 'aspect', 'Moon', 'Sun', 'sextile', 'Sun–Moon Sextile', 'Opportunities arise naturally from the flowing cooperation between your will and your feelings.', '{opportunity,flow,cooperation,ease}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('a0605c25-54c7-4fe4-87c9-e190b161ccc0', 'en', 'aspect', 'Mars', 'Sun', 'conjunction', 'Sun–Mars Conjunction', 'Vitality and assertive drive are amplified. You act decisively and project a confident, energetic presence.', '{energy,action,drive,assertive}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('da64ce20-0040-4e10-a87e-cd39129681bf', 'en', 'aspect', 'Mars', 'Sun', 'square', 'Sun–Mars Square', 'Frustrated will creates tension that fuels ambitious striving. Learn to channel aggression constructively.', '{friction,ambition,aggression,striving}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('5cd27d27-d144-459a-993d-f2085929b8d4', 'en', 'aspect', 'Mars', 'Sun', 'trine', 'Sun–Mars Trine', 'Your drive and identity work in elegant harmony. Physical courage and confident action come naturally.', '{courage,action,harmony,physical}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('ba9d3027-e641-43a7-8d5a-9960877aa271', 'en', 'aspect', 'Saturn', 'Sun', 'conjunction', 'Sun–Saturn Conjunction', 'Discipline and responsibility are woven into your identity. Authority and structure define your path.', '{discipline,authority,responsibility,structure}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('e0902f4f-cf0b-4851-bf96-cf3e2a3e3077', 'en', 'aspect', 'Saturn', 'Sun', 'square', 'Sun–Saturn Square', 'Self-doubt and external obstacles test your solar purpose. Persistence in the face of limitation is your key lesson.', '{limitation,perseverance,test,maturity}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('516f8925-d8fc-45ea-b9de-46f84fc8368c', 'en', 'aspect', 'Jupiter', 'Sun', 'trine', 'Sun–Jupiter Trine', 'Luck, optimism, and expansive vision support your self-expression. You attract abundance with relative ease.', '{luck,expansion,optimism,abundance}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('512eec24-f1a2-4ff0-9e41-ff463bfaaf7f', 'en', 'aspect', 'Venus', 'Sun', 'conjunction', 'Sun–Venus Conjunction', 'Charm, aesthetics, and the desire for harmony are central to how you present yourself.', '{charm,beauty,social,harmony}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('335634a8-c29d-460f-805a-4af3b4a3cbcd', 'vi', 'planet_in_sign', 'Sun', 'Aries', NULL, 'Mặt Trời trong Bạch Dương', 'Bản sắc cốt lõi của bạn được thúc đẩy bởi sự chủ động, can đảm và tinh thần tiên phong. Bạn dẫn đầu bằng sự táo bạo.', '{"lãnh đạo","dũng cảm",lửa,"chủ động"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('1ba0c31b-35cd-4432-a34a-8a56b5f24880', 'vi', 'planet_in_sign', 'Sun', 'Taurus', NULL, 'Mặt Trời trong Kim Ngưu', 'Bản sắc của bạn được neo chặt vào sự ổn định, khoái cảm giác quan và sự kiên nhẫn bền bỉ. Bạn xây dựng chậm nhưng bền vững.', '{"ổn định",đất,"kiên nhẫn","vật chất"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('51f8dc5f-4c68-4e44-891d-f9dcce717444', 'vi', 'planet_in_sign', 'Sun', 'Gemini', NULL, 'Mặt Trời trong Song Tử', 'Bản sắc của bạn được định hình bởi sự tò mò, linh hoạt và khả năng giao tiếp xuất sắc.', '{"giao tiếp","không khí",đôi,"tò mò"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('afed8fbc-74f9-4ce1-85ca-42e65e0b93c3', 'vi', 'planet_in_sign', 'Sun', 'Cancer', NULL, 'Mặt Trời trong Cự Giải', 'Chiều sâu cảm xúc, bản năng nuôi dưỡng và gắn kết mạnh mẽ với gia đình định hình cái tôi cốt lõi của bạn.', '{"nuôi dưỡng",nước,"gia đình","cảm xúc"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('84e5cab8-f0ad-46bd-95c3-7fb7a81f5e16', 'vi', 'planet_in_sign', 'Sun', 'Leo', NULL, 'Mặt Trời trong Sư Tử', 'Sáng tạo, tự thể hiện và trái tim ấm áp hào phóng tạo nên bản sắc của bạn. Bạn tỏa sáng nhất khi được đứng trên sân khấu.', '{"sáng tạo",lửa,"hào phóng","tự tin"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('3e93da0a-e21b-41b1-8be1-34b12fa2a187', 'vi', 'planet_in_sign', 'Sun', 'Virgo', NULL, 'Mặt Trời trong Xử Nữ', 'Sự phân tích chính xác, định hướng phục vụ và mắt tinh tế là dấu hiệu của bản thể mặt trời của bạn.', '{"phân tích",đất,"phục vụ","chi tiết"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('c49afffb-4d3e-4bcf-bbd1-ee01373c8b7c', 'vi', 'planet_in_sign', 'Sun', 'Libra', NULL, 'Mặt Trời trong Thiên Bình', 'Cân bằng, hài hòa và thẩm mỹ tinh tế định nghĩa bạn là ai. Bạn tốt nhất trong quan hệ đối tác và ngoại giao.', '{"cân bằng","không khí","hài hòa","ngoại giao"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('888fb75a-05bd-4f05-be79-c017a28fde6e', 'vi', 'planet_in_sign', 'Sun', 'Scorpio', NULL, 'Mặt Trời trong Bọ Cạp', 'Cường độ, sức mạnh biến đổi và cái nhìn sâu sắc xuyên suốt định hình bản sắc cốt lõi của bạn.', '{"cường độ",nước,"biến đổi","quyền lực"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('e3dbec3f-2780-4053-8b18-d83a37c5c0b4', 'vi', 'planet_in_sign', 'Sun', 'Sagittarius', NULL, 'Mặt Trời trong Nhân Mã', 'Tầm nhìn triết học, tình yêu tự do và cuộc tìm kiếm lạc quan về chân lý định nghĩa bản chất mặt trời của bạn.', '{"tự do",lửa,"triết học","lạc quan"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('2d935a76-e408-419e-a1fc-c8b06fdf5cf0', 'vi', 'planet_in_sign', 'Sun', 'Capricorn', NULL, 'Mặt Trời trong Ma Kết', 'Tham vọng có kỷ luật, tư duy cấu trúc và kế hoạch dài hạn là nền tảng của bản sắc của bạn.', '{"tham vọng",đất,"kỷ luật","sự nghiệp"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('34138ca9-ed0e-4bdd-a874-7019af781515', 'vi', 'planet_in_sign', 'Sun', 'Aquarius', NULL, 'Mặt Trời trong Bảo Bình', 'Lý tưởng nhân đạo, độc lập trí tuệ và khao khát đổi mới định hình ý thức về bản thân của bạn.', '{"đổi mới","không khí","nhân đạo","độc lập"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('5d42c3a7-e178-4443-8674-b8b30818d74f', 'vi', 'planet_in_sign', 'Sun', 'Pisces', NULL, 'Mặt Trời trong Song Ngư', 'Lòng trắc ẩn, trí tưởng tượng và sự thấu cảm huyền bí với thế giới vô hình định nghĩa bản sắc mặt trời của bạn.', '{"trắc ẩn",nước,"huyền bí","tưởng tượng"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('dc227c9c-3535-4675-a83b-aae871c9fbf6', 'vi', 'planet_in_sign', 'Moon', 'Aries', NULL, 'Mặt Trăng trong Bạch Dương', 'Phản ứng cảm xúc của bạn nhanh chóng, trực tiếp và bốc lửa. Bạn cần hành động để cảm thấy hài lòng về mặt cảm xúc.', '{"bốc đồng",lửa,"cảm xúc","phản ứng"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('78ff5f56-a9bf-495d-a873-e72f58e9f81a', 'vi', 'planet_in_sign', 'Moon', 'Taurus', NULL, 'Mặt Trăng trong Kim Ngưu', 'An toàn cảm xúc đến qua sự thoải mái, thói quen và niềm vui giác quan. Bạn trung thành và kiên định sâu sắc.', '{"an toàn",đất,"thoải mái","kiên định"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('2530a288-5144-406a-8419-807ca9637236', 'vi', 'planet_in_sign', 'Moon', 'Gemini', NULL, 'Mặt Trăng trong Song Tử', 'Sức khỏe cảm xúc phụ thuộc vào kích thích tinh thần và sự đa dạng. Bạn xử lý cảm xúc qua giao tiếp.', '{"tinh thần","không khí","ngôn từ","thay đổi"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('2eff89c3-d1df-4857-a373-46fefc7c94e9', 'vi', 'planet_in_sign', 'Moon', 'Cancer', NULL, 'Mặt Trăng trong Cự Giải', 'Bạn là ngôi nhà tự nhiên của Mặt Trăng: rất trực giác, nuôi dưỡng và nhạy cảm với các dòng chảy cảm xúc.', '{"trực giác",nước,"nuôi dưỡng",nhà}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('6a7c4f5e-4c32-4b78-aa35-e8127af16bf9', 'vi', 'planet_in_sign', 'Moon', 'Leo', NULL, 'Mặt Trăng trong Sư Tử', 'Bạn cần sự công nhận và ấm áp để được nuôi dưỡng về mặt cảm xúc. Kịch tính và sáng tạo thúc đẩy thế giới nội tâm của bạn.', '{"công nhận",lửa,"kịch tính","ấm áp"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('1d938b73-62dd-439d-a89f-175f74d96339', 'vi', 'planet_in_sign', 'Moon', 'Virgo', NULL, 'Mặt Trăng trong Xử Nữ', 'Sự thoải mái cảm xúc đến qua sự hữu ích, có tổ chức và qua các hành động chăm sóc thực tế.', '{"thực tế",đất,"phục vụ","có tổ chức"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('d5fbf64b-3779-4438-bd4b-99d8b5724175', 'vi', 'planet_in_sign', 'Moon', 'Libra', NULL, 'Mặt Trăng trong Thiên Bình', 'Bạn tìm thấy sự bình yên cảm xúc trong vẻ đẹp, sự công bằng và các mối quan hệ hài hòa.', '{"hài hòa","không khí","vẻ đẹp","mối quan hệ"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('be0b87fb-047e-4807-a781-361f2406321f', 'vi', 'planet_in_sign', 'Moon', 'Scorpio', NULL, 'Mặt Trăng trong Bọ Cạp', 'Cảm xúc chạy sâu và mãnh liệt. Bạn bảo vệ sự dễ bị tổn thương cẩn thận nhưng cảm nhận mọi thứ sâu sắc.', '{"mãnh liệt",nước,"chiều sâu","riêng tư"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('c4b216d9-842c-47b7-9a89-aabb096fd59f', 'vi', 'planet_in_sign', 'Moon', 'Sagittarius', NULL, 'Mặt Trăng trong Nhân Mã', 'Tự do cảm xúc và việc theo đuổi ý nghĩa mang lại niềm vui nội tâm cho bạn.', '{"tự do",lửa,"ý nghĩa","phiêu lưu"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('f28f3f00-60eb-4706-a672-5974abe539e9', 'vi', 'planet_in_sign', 'Moon', 'Capricorn', NULL, 'Mặt Trăng trong Ma Kết', 'Bạn quản lý cảm xúc với sự kiềm chế và tìm thấy sự an toàn qua thành tích.', '{"kiềm chế",đất,"thành tích","điềm tĩnh"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('2e5d985f-0a56-4bd2-a9c7-b431de83e98c', 'vi', 'planet_in_sign', 'Moon', 'Aquarius', NULL, 'Mặt Trăng trong Bảo Bình', 'Nhu cầu cảm xúc được đáp ứng qua cộng đồng trí tuệ và các lý tưởng hơn là sự thân mật cá nhân.', '{"cộng đồng","không khí","lý tưởng","tách biệt"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('dea39e3d-6951-49aa-b5c0-d5def16abc2c', 'vi', 'planet_in_sign', 'Moon', 'Pisces', NULL, 'Mặt Trăng trong Song Ngư', 'Bạn có sự đồng cảm vô hạn và được hòa hợp tâm linh, hấp thụ bầu không khí cảm xúc xung quanh bạn.', '{"đồng cảm",nước,"tâm linh","nhạy cảm"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('19197be8-1d13-4a8f-8bfd-4a270d0af9b4', 'vi', 'planet_in_house', 'Sun', '1', NULL, 'Mặt Trời trong Nhà 1', 'Bạn thể hiện bản sắc mạnh mẽ và tự tin. Cuộc sống là sự thể hiện trực tiếp của ý chí cá nhân.', '{"bản sắc","bản thân","thể hiện","sinh lực"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('045fa621-d1c6-4205-9804-cb61e423ca5c', 'vi', 'planet_in_house', 'Sun', '2', NULL, 'Mặt Trời trong Nhà 2', 'Cảm giác về bản thân của bạn gắn chặt với an ninh vật chất, các giá trị cá nhân và sự độc lập tài chính.', '{"tiền bạc","giá trị","vật chất","an ninh"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('d9323139-7f06-4529-abd6-b1773dc768d9', 'vi', 'planet_in_house', 'Sun', '4', NULL, 'Mặt Trời trong Nhà 4', 'Nhà cửa, tổ tiên và rễ gia đình là nền tảng cho bản sắc và mục đích sống của bạn.', '{nhà,"gia đình","gốc rễ","riêng tư"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('f6640e37-86c2-49c8-b8a6-fe2c00e78fa9', 'vi', 'planet_in_house', 'Sun', '7', NULL, 'Mặt Trời trong Nhà 7', 'Quan hệ đối tác là tấm gương phản chiếu cái tôi sâu thẳm nhất của bạn.', '{"đối tác","hôn nhân",gương,"người khác"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('806465d7-119c-493e-a3f4-a39f4c5dd925', 'vi', 'planet_in_house', 'Sun', '10', NULL, 'Mặt Trời trong Nhà 10', 'Sự nghiệp, danh tiếng và thành tích là đấu trường mà bản sắc mặt trời của bạn tỏa sáng rực rỡ nhất.', '{"sự nghiệp","địa vị","công cộng","tham vọng"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('cb452f79-ec8e-4783-bc93-a670d3063a4c', 'vi', 'aspect', 'Moon', 'Sun', 'conjunction', 'Hội tinh Mặt Trời – Mặt Trăng', 'Ý chí có ý thức và bản năng cảm xúc của bạn hợp nhất thành một động lực thống nhất. Điều bạn muốn và điều bạn cảm nhận hiếm khi xung đột.', '{"thống nhất","bản sắc","bản năng","hội tụ"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('f2e11ffd-38dd-4d33-81cd-0d7561e466e5', 'vi', 'aspect', 'Moon', 'Sun', 'trine', 'Tam hợp Mặt Trời – Mặt Trăng', 'Sự hòa hợp tự nhiên giữa bản ngã và bản chất cảm xúc tạo ra tính cách hội tụ và tự tin.', '{"hài hòa","dễ dàng","hội tụ","tự tin"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('e0d6d6c8-5fc0-453f-8454-938183758e51', 'vi', 'aspect', 'Moon', 'Sun', 'square', 'Vuông góc Mặt Trời – Mặt Trăng', 'Căng thẳng nội tâm giữa mong muốn và nhu cầu cảm xúc thúc đẩy sự phát triển qua những thách thức lặp đi lặp lại.', '{"căng thẳng","phát triển","thách thức","xung đột"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('6eeb4c65-4ffe-4d9e-abc9-6eac752149af', 'vi', 'aspect', 'Moon', 'Sun', 'opposition', 'Đối chiếu Mặt Trời – Mặt Trăng', 'Sự phân cực giữa tự khẳng định và tiếp nhận cảm xúc diễn ra qua sự chiếu lên người khác.', '{"phân cực",chiếu,"cân bằng","nhận thức"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('8b5659d0-4c1b-42f5-b5b7-5f59a69837dd', 'vi', 'aspect', 'Moon', 'Sun', 'sextile', 'Lục phân Mặt Trời – Mặt Trăng', 'Cơ hội nảy sinh tự nhiên từ sự hợp tác trôi chảy giữa ý chí và cảm xúc của bạn.', '{"cơ hội","dòng chảy","hợp tác","dễ dàng"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('ea6ab0b7-a677-494f-ad09-b8a231a57c6f', 'vi', 'aspect', 'Mars', 'Sun', 'conjunction', 'Hội tinh Mặt Trời – Sao Hỏa', 'Sinh lực và động lực quyết đoán được khuếch đại. Bạn hành động quyết đoán và tỏa ra sự tự tin năng động.', '{"năng lượng","hành động","động lực","quyết đoán"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('f84f08d4-fb57-40ef-96c1-766f1ac0dd95', 'vi', 'aspect', 'Mars', 'Sun', 'square', 'Vuông góc Mặt Trời – Sao Hỏa', 'Ý chí bị cản trở tạo ra căng thẳng thúc đẩy khát vọng đầy tham vọng. Học cách hướng sự hung hăng một cách xây dựng.', '{"ma sát","tham vọng","hung hăng","phấn đấu"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('eba3ee7e-adbd-4018-99e7-fc5e5ae8b646', 'vi', 'aspect', 'Saturn', 'Sun', 'conjunction', 'Hội tinh Mặt Trời – Sao Thổ', 'Kỷ luật và trách nhiệm được dệt vào bản sắc của bạn. Thẩm quyền và cấu trúc định nghĩa con đường của bạn.', '{"kỷ luật","thẩm quyền","trách nhiệm","cấu trúc"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('4389b329-4237-4cc2-9b5a-674a36ff2a9b', 'vi', 'aspect', 'Jupiter', 'Sun', 'trine', 'Tam hợp Mặt Trời – Sao Mộc', 'May mắn, lạc quan và tầm nhìn mở rộng hỗ trợ sự tự thể hiện của bạn. Bạn thu hút sự phong phú một cách tương đối dễ dàng.', '{"may mắn","mở rộng","lạc quan","phong phú"}', true, '2026-07-29 13:35:22.149227+00', '2026-07-29 13:35:22.149227+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('2904c809-d076-4299-867b-4fb1f5614597', 'en', 'planet_in_sign', 'Mercury', 'Aries', NULL, 'Mercury in Aries', 'With Mercury in Aries, the themes of communication and intellect take on a direct, pioneering, and energetic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","direct, pioneering",energetic}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('cd4a2a23-2a36-435b-8e24-ca4e52c78ec3', 'vi', 'planet_in_sign', 'Mercury', 'Aries', NULL, 'Sao Mercury ở Aries', 'Với Sao Mercury ở Aries, các chủ đề về giao tiếp và trí tuệ mang một sắc thái trực tiếp, tiên phong và tràn đầy năng lượng. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","trực tiếp, tiên phong","tràn đầy năng lượng"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('8cf7f493-9626-42cd-b8fa-65a53e03d68f', 'en', 'planet_in_sign', 'Mercury', 'Taurus', NULL, 'Mercury in Taurus', 'With Mercury in Taurus, the themes of communication and intellect take on a grounded, persistent, and sensual flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","grounded, persistent",sensual}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('21fe16e6-166f-4aaa-80ce-7aed09986794', 'vi', 'planet_in_sign', 'Mercury', 'Taurus', NULL, 'Sao Mercury ở Taurus', 'Với Sao Mercury ở Taurus, các chủ đề về giao tiếp và trí tuệ mang một sắc thái thực tế, kiên trì và gợi cảm. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","thực tế, kiên trì","gợi cảm"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('78e79d82-dc8e-40a8-8313-bea252e1650e', 'en', 'planet_in_sign', 'Mercury', 'Gemini', NULL, 'Mercury in Gemini', 'With Mercury in Gemini, the themes of communication and intellect take on a curious, adaptable, and communicative flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","curious, adaptable",communicative}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('c28d4ea5-a610-456c-b3c2-4df0ce285095', 'vi', 'planet_in_sign', 'Mercury', 'Gemini', NULL, 'Sao Mercury ở Gemini', 'Với Sao Mercury ở Gemini, các chủ đề về giao tiếp và trí tuệ mang một sắc thái tò mò, dễ thích nghi và hoạt ngôn. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","tò mò, dễ thích nghi","hoạt ngôn"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('1b684d60-7002-48f9-aa20-b48947c8ae12', 'en', 'planet_in_sign', 'Mercury', 'Cancer', NULL, 'Mercury in Cancer', 'With Mercury in Cancer, the themes of communication and intellect take on a intuitive, nurturing, and emotional flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","intuitive, nurturing",emotional}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('e7d18d98-631e-49c2-9167-a8a2665b0f74', 'vi', 'planet_in_sign', 'Mercury', 'Cancer', NULL, 'Sao Mercury ở Cancer', 'Với Sao Mercury ở Cancer, các chủ đề về giao tiếp và trí tuệ mang một sắc thái trực giác, nuôi dưỡng và giàu cảm xúc. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","trực giác, nuôi dưỡng","giàu cảm xúc"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('7c2e0321-6643-4ad6-8d69-37224bb9e4a9', 'en', 'planet_in_sign', 'Mercury', 'Leo', NULL, 'Mercury in Leo', 'With Mercury in Leo, the themes of communication and intellect take on a dramatic, expressive, and confident flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","dramatic, expressive",confident}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('daa5bbd4-df1e-4bf7-b045-c1550f1d44a9', 'vi', 'planet_in_sign', 'Mercury', 'Leo', NULL, 'Sao Mercury ở Leo', 'Với Sao Mercury ở Leo, các chủ đề về giao tiếp và trí tuệ mang một sắc thái kịch tính, biểu cảm và tự tin. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","kịch tính, biểu cảm","tự tin"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('653c614b-5794-4436-8f82-3034c88c2a48', 'en', 'planet_in_sign', 'Mercury', 'Virgo', NULL, 'Mercury in Virgo', 'With Mercury in Virgo, the themes of communication and intellect take on a analytical, practical, and detail-oriented flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","analytical, practical",detail-oriented}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('60cd3963-1ea7-4f3f-b5c2-8b6638067fc3', 'vi', 'planet_in_sign', 'Mercury', 'Virgo', NULL, 'Sao Mercury ở Virgo', 'Với Sao Mercury ở Virgo, các chủ đề về giao tiếp và trí tuệ mang một sắc thái phân tích, thực tế và chú ý đến chi tiết. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","phân tích, thực tế","chú ý đến chi tiết"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('fdac81a8-9109-4367-95a1-81cd8a963553', 'en', 'planet_in_sign', 'Mercury', 'Libra', NULL, 'Mercury in Libra', 'With Mercury in Libra, the themes of communication and intellect take on a harmonious, diplomatic, and partnership-focused flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","harmonious, diplomatic",partnership-focused}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('713f6846-433c-4411-b4a1-a0500409fa1c', 'vi', 'planet_in_sign', 'Mercury', 'Libra', NULL, 'Sao Mercury ở Libra', 'Với Sao Mercury ở Libra, các chủ đề về giao tiếp và trí tuệ mang một sắc thái hài hòa, ngoại giao và hướng tới quan hệ đối tác. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","hài hòa, ngoại giao","hướng tới quan hệ đối tác"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('dc442860-e468-411d-822a-929300bd6f3b', 'en', 'planet_in_sign', 'Mercury', 'Scorpio', NULL, 'Mercury in Scorpio', 'With Mercury in Scorpio, the themes of communication and intellect take on a intense, passionate, and investigative flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","intense, passionate",investigative}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('278f4a53-2d1f-44c5-873d-be269f70b107', 'vi', 'planet_in_sign', 'Mercury', 'Scorpio', NULL, 'Sao Mercury ở Scorpio', 'Với Sao Mercury ở Scorpio, các chủ đề về giao tiếp và trí tuệ mang một sắc thái mãnh liệt, đam mê và thích điều tra. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","mãnh liệt, đam mê","thích điều tra"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('c2a44692-3cd6-4095-a121-0ff5194b2c55', 'en', 'planet_in_sign', 'Mercury', 'Sagittarius', NULL, 'Mercury in Sagittarius', 'With Mercury in Sagittarius, the themes of communication and intellect take on a adventurous, philosophical, and optimistic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","adventurous, philosophical",optimistic}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('60902c08-36a2-4378-8dba-63a4e546abe5', 'vi', 'planet_in_sign', 'Mercury', 'Sagittarius', NULL, 'Sao Mercury ở Sagittarius', 'Với Sao Mercury ở Sagittarius, các chủ đề về giao tiếp và trí tuệ mang một sắc thái phiêu lưu, triết lý và lạc quan. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giao tiếp","trí tuệ","phiêu lưu, triết lý","lạc quan"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('0acf2ab5-250c-48b3-9c2d-301c1cf06096', 'en', 'planet_in_sign', 'Mercury', 'Capricorn', NULL, 'Mercury in Capricorn', 'With Mercury in Capricorn, the themes of communication and intellect take on a ambitious, disciplined, and pragmatic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"communication and intellect","ambitious, disciplined",pragmatic}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
