INSERT INTO public.interpretation_templates VALUES ('018153d0-5b34-4867-88de-e0b2b63a2080', 'vi', 'planet_in_sign', 'Neptune', 'Aquarius', NULL, 'Sao Neptune ở Aquarius', 'Với Sao Neptune ở Aquarius, các chủ đề về giấc mơ, ảo tưởng và tâm linh mang một sắc thái tiến bộ, độc đáo và có tầm nhìn. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giấc mơ, ảo tưởng","tâm linh","tiến bộ, độc đáo","có tầm nhìn"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('1646dc40-a3e9-4e35-b108-08943273db9a', 'en', 'planet_in_sign', 'Neptune', 'Pisces', NULL, 'Neptune in Pisces', 'With Neptune in Pisces, the themes of dreams, illusion, and spirituality take on a empathetic, mystical, and imaginative flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"dreams, illusion",spirituality,"empathetic, mystical",imaginative}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('409b0a4b-300b-4486-b49e-f9548e7b24cf', 'vi', 'planet_in_sign', 'Neptune', 'Pisces', NULL, 'Sao Neptune ở Pisces', 'Với Sao Neptune ở Pisces, các chủ đề về giấc mơ, ảo tưởng và tâm linh mang một sắc thái đồng cảm, huyền bí và giàu trí tưởng tượng. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"giấc mơ, ảo tưởng","tâm linh","đồng cảm, huyền bí","giàu trí tưởng tượng"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('c20ef501-b32a-47a8-9c96-98f463693790', 'en', 'planet_in_sign', 'Pluto', 'Aries', NULL, 'Pluto in Aries', 'With Pluto in Aries, the themes of transformation, power, and rebirth take on a direct, pioneering, and energetic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"transformation, power",rebirth,"direct, pioneering",energetic}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('1263b129-567a-40f2-94b8-7752c6a0a332', 'vi', 'planet_in_sign', 'Pluto', 'Aries', NULL, 'Sao Pluto ở Aries', 'Với Sao Pluto ở Aries, các chủ đề về biến đổi, quyền lực và tái sinh mang một sắc thái trực tiếp, tiên phong và tràn đầy năng lượng. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"biến đổi, quyền lực","tái sinh","trực tiếp, tiên phong","tràn đầy năng lượng"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
