INSERT INTO public.interpretation_templates VALUES ('2ad7c21b-1b38-4fbc-8f61-c15caa044125', 'en', 'planet_in_sign', 'North Node', 'Aries', NULL, 'North Node in Aries', 'With North Node in Aries, the themes of karmic destiny and life purpose take on a direct, pioneering, and energetic flavor. This placement infuses your chart with unique characteristics, blending the planet''s core energy with the sign''s modality and element.', '{"karmic destiny and life purpose","direct, pioneering",energetic}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
INSERT INTO public.interpretation_templates VALUES ('46e0d389-9fa8-4630-be2a-7b18baf52bee', 'vi', 'planet_in_sign', 'North Node', 'Aries', NULL, 'Bắc Giao ở Aries', 'Với Bắc Giao ở Aries, các chủ đề về định mệnh nghiệp chướng và mục đích sống mang một sắc thái trực tiếp, tiên phong và tràn đầy năng lượng. Vị trí này truyền vào bản đồ sao của bạn những đặc điểm độc đáo, kết hợp năng lượng cốt lõi của hành tinh với đặc tính và nguyên tố của cung hoàng đạo.', '{"định mệnh nghiệp chướng","mục đích sống","trực tiếp, tiên phong","tràn đầy năng lượng"}', true, '2026-07-29 14:25:49.635906+00', '2026-07-29 14:25:49.635906+00') ON CONFLICT DO NOTHING;
